          "absolute inset-0 flex items-center justify-center bg-[#F4F2EA] z-0",
          imgError ? "opacity-100" : "opacity-0"
        )}>
          <span className="text-sm font-medium text-[#5F706C]/50 uppercase tracking-wider text-center px-4">
            Product image unavailable
          </span>
        </div>

        <img 
          src={product.image} 
          alt={product.title}
          loading="lazy"
          onError={() => setImgError(true)}
          className={cn(
            "relative z-0 object-cover w-full h-full transition-transform duration-[400ms] ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:scale-[1.02]",
            imgError && "opacity-0"
          )}
        />

        {product.badge && (
          <Badge variant="secondary" className="absolute top-3 left-3 z-10 bg-white/95 backdrop-blur-sm text-[11px] font-bold tracking-wider text-[#183330] rounded-[4px] px-2 py-0.5 hover:bg-white/95">
            {product.badge}
          </Badge>
        )}

        {/* Wishlist Button */}
        <Button 
          variant="ghost"
          size="icon"
          onClick={toggleWishlist}
          aria-label="Add to wishlist"
          aria-pressed={isWishlisted}
          className="absolute top-2 right-2 z-10 w-8 h-8 rounded-full hover:bg-white/20 transition-colors"
        >
          <Heart 
            className={cn(
              "w-[18px] h-[18px] transition-colors", 
              isWishlisted ? "fill-[#D2A01F] text-[#D2A01F]" : "text-[#183330] hover:text-[#D2A01F]"
            )} 
            strokeWidth={isWishlisted ? 0 : 1.5}
          />
        </Button>
      </div>

      {/* Product Metadata */}
      <div className="flex flex-col flex-grow">
        {/* Rating */}
        {product.rating && (
          <div className="flex items-center gap-1 text-[12px] text-[#5F706C] mb-1.5">
            <div className="flex items-center text-[#D2A01F]">
              <Star className="w-[14px] h-[14px] fill-current" />
            </div>
            <span className="font-medium text-[#183330]">{product.rating}</span>
            <span>({product.reviewCount})</span>
          </div>
        )}

        {/* Title */}
        <h3 className="text-[15px] text-[#183330] font-medium leading-snug line-clamp-2 mb-2 group-hover:text-[#07514D] transition-colors">
          {product.title}
        </h3>

        {/* Pricing */}
        <div className="flex items-baseline gap-2 mt-auto">
          <span className="text-[15px] font-semibold text-[#183330]">₹{product.price}</span>
          {product.compareAtPrice && (
            <span className="text-[13px] text-[#5F706C] line-through">₹{product.compareAtPrice}</span>
          )}
          {product.discountPercentage && (
            <span className="text-[12px] font-semibold text-[#D2A01F] ml-1">
              {product.discountPercentage}% OFF
            </span>
          )}
        </div>

        {/* Personalisation/Delivery Info */}
        {(product.isPersonalised || product.deliveryInfo) && (
          <div className="mt-2.5 flex flex-col gap-1">
            {product.isPersonalised && (
              <span className="text-[12px] font-medium text-[#5F706C] flex items-center gap-1 transition-transform">
                Make it personal <ArrowRight className="w-3 h-3 transition-transform group-hover:translate-x-1" />
              </span>
            )}
            {product.deliveryInfo && (
              <span className="text-[12px] text-[#07514D] font-medium">
                {product.deliveryInfo}
              </span>
            )}
          </div>
        )}
      </div>
    </Link>
  );
}

"use client";

import { useState, useRef, useEffect, KeyboardEvent } from "react";
import { ChevronLeft, ChevronRight, Maximize2, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";

interface ProductGalleryProps {
  images: string[];
  altText: string;
}

export function ProductGallery({ images, altText }: ProductGalleryProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  // Sync scroll position when index changes via thumbnails or buttons
  useEffect(() => {
    if (scrollContainerRef.current) {
      const container = scrollContainerRef.current;
      const width = container.clientWidth;
      container.scrollTo({
        left: width * currentIndex,
        behavior: "smooth"
      });
    }
  }, [currentIndex]);

  // Update index based on scroll position (for mobile swipe/horizontal scroll)
  const handleScroll = () => {
    if (!scrollContainerRef.current) return;
    const container = scrollContainerRef.current;
    const scrollPosition = container.scrollLeft;
    const width = container.clientWidth;
    const newIndex = Math.round(scrollPosition / width);
    if (newIndex !== currentIndex && newIndex >= 0 && newIndex < images.length) {
      setCurrentIndex(newIndex);
    }
  };

  const nextImage = () => {
    if (currentIndex < images.length - 1) {
      setCurrentIndex(prev => prev + 1);
    }
  };

  const prevImage = () => {
    if (currentIndex > 0) {
      setCurrentIndex(prev => prev - 1);
    }
  };

  const handleKeyDown = (e: KeyboardEvent) => {
    if (e.key === "ArrowRight") nextImage();
    if (e.key === "ArrowLeft") prevImage();
  };

  useEffect(() => {
    const handleGlobalKeyDown = (e: globalThis.KeyboardEvent) => {
      if (isFullscreen) {
        if (e.key === "Escape") setIsFullscreen(false);
        if (e.key === "ArrowRight") nextImage();
        if (e.key === "ArrowLeft") prevImage();
      }
    };
    window.addEventListener("keydown", handleGlobalKeyDown);
    return () => window.removeEventListener("keydown", handleGlobalKeyDown);
  }, [isFullscreen]);

  if (!images || images.length === 0) return null;

  return (
    <>
      <div 
        className="flex flex-col-reverse lg:flex-row gap-4 w-full select-none"
        onKeyDown={handleKeyDown}
        tabIndex={0}
      >

        {/* Thumbnails (Hidden on very small screens, visible lg, or bottom row md) */}
        <div className="hidden lg:flex flex-col gap-3 w-[72px] xl:w-[86px] shrink-0">
          {images.map((img, idx) => (
            <button
              key={idx}
              onClick={() => setCurrentIndex(idx)}
              className={cn(
                "relative w-full aspect-[4/5] rounded-md overflow-hidden bg-[#F4F2EA] transition-all",
                currentIndex === idx ? "ring-1 ring-[#183330] ring-offset-2" : "opacity-60 hover:opacity-100"
              )}
              aria-label={`View image ${idx + 1}`}
              aria-current={currentIndex === idx}
            >
              <img 
                src={img} 
                alt={`Thumbnail ${idx + 1}`}
                className="w-full h-full object-cover"
              />
            </button>
          ))}
        </div>

        {/* Main Image Viewport */}
        <div className="relative flex-1 bg-[#F4F2EA] rounded-lg overflow-hidden group">

          <div 
            ref={scrollContainerRef}
            className="flex w-full aspect-[4/5] md:aspect-[1/1] lg:aspect-[4/5] overflow-x-auto snap-x snap-mandatory hide-scrollbar"
            onScroll={handleScroll}
          >
            {images.map((img, idx) => (
              <div key={idx} className="w-full shrink-0 snap-center relative h-full">
                <img 
                  src={img} 
                  alt={`${altText} - View ${idx + 1}`}
                  className="w-full h-full object-cover"
                />
              </div>
            ))}
          </div>

          {/* Floating Controls (Desktop Hover) */}
          {images.length > 1 && (
            <>
              <button 
                onClick={prevImage}
                disabled={currentIndex === 0}
                className="absolute left-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-white/90 backdrop-blur shadow-sm items-center justify-center text-[#183330] hover:bg-white disabled:opacity-0 transition-all opacity-0 group-hover:opacity-100 hidden md:flex"
                aria-label="Previous image"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
              <button 
                onClick={nextImage}
                disabled={currentIndex === images.length - 1}
                className="absolute right-4 top-1/2 -translate-y-1/2 w-10 h-10 rounded-full bg-white/90 backdrop-blur shadow-sm items-center justify-center text-[#183330] hover:bg-white disabled:opacity-0 transition-all opacity-0 group-hover:opacity-100 hidden md:flex"
                aria-label="Next image"
              >
                <ChevronRight className="w-5 h-5" />
              </button>
            </>
          )}

          {/* Fullscreen Trigger */}
          <button
            onClick={() => setIsFullscreen(true)}
            className="absolute top-4 right-4 w-9 h-9 rounded-full bg-white/80 backdrop-blur flex items-center justify-center text-[#183330] hover:bg-white transition-colors opacity-0 group-hover:opacity-100 focus:opacity-100"
            aria-label="View fullscreen"
          >
            <Maximize2 className="w-4 h-4" />
          </button>

          {/* Mobile Pagination Dots */}
          {images.length > 1 && (
            <div className="absolute bottom-4 left-0 right-0 flex justify-center gap-1.5 lg:hidden">
              {images.map((_, idx) => (
                <button
                  key={idx}
                  onClick={() => setCurrentIndex(idx)}
                  className={cn(
                    "w-1.5 h-1.5 rounded-full transition-all",
                    currentIndex === idx ? "bg-[#183330] w-3" : "bg-black/20"
                  )}
                  aria-label={`Go to slide ${idx + 1}`}
                />
              ))}
            </div>
          )}

        </div>
      </div>

      {/* Fullscreen Lightbox */}
      {isFullscreen && (
        <div className="fixed inset-0 z-[100] bg-white flex flex-col items-center justify-center animate-in fade-in duration-200">
          <div className="absolute top-0 w-full flex items-center justify-between p-4 md:p-6 z-10">
            <span className="text-[13px] font-medium text-[#5F706C] tracking-widest uppercase">
              {currentIndex + 1} / {images.length}
            </span>
            <Button 
              variant="ghost" 
              size="icon" 
              onClick={() => setIsFullscreen(false)}
              className="text-[#183330] hover:bg-[#F4F2EA] rounded-full w-10 h-10"
            >
              <X className="w-5 h-5" />
            </Button>
          </div>

          <div className="relative w-full max-w-5xl h-[80vh] flex items-center justify-center px-4">
            <img 
              src={images[currentIndex]} 
              alt={`${altText} - Fullscreen View ${currentIndex + 1}`}
              className="max-w-full max-h-full object-contain"
            />

            {images.length > 1 && (
              <>
                <button 
                  onClick={prevImage}
                  disabled={currentIndex === 0}
                  className="absolute left-4 md:left-8 top-1/2 -translate-y-1/2 w-12 h-12 rounded-full bg-[#F4F2EA] flex items-center justify-center text-[#183330] hover:bg-[#E4E7E2] disabled:opacity-30 transition-all"
                >
                  <ChevronLeft className="w-6 h-6" />
                </button>
                <button 
                  onClick={nextImage}
                  disabled={currentIndex === images.length - 1}
                  className="absolute right-4 md:right-8 top-1/2 -translate-y-1/2 w-12 h-12 rounded-full bg-[#F4F2EA] flex items-center justify-center text-[#183330] hover:bg-[#E4E7E2] disabled:opacity-30 transition-all"
                >
                  <ChevronRight className="w-6 h-6" />
                </button>
              </>
            )}
          </div>
        </div>
      )}
    </>
  );
}

"use client";

import { useState } from "react";
import { Heart, Star, MapPin, Check, Plus, Minus, ShieldCheck, Gift, Truck } from "lucide-react";
import { cn } from "@/lib/utils";
import { Product } from "@/data/products";
import { useCart } from "@/components/commerce/CartContext";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Separator } from "@/components/ui/separator";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { toast } from "sonner";

interface ProductInfoProps {
  product: Product;
}

export function ProductInfo({ product }: ProductInfoProps) {
  const { addItem } = useCart();
  const [isWishlisted, setIsWishlisted] = useState(false);
  const [quantity, setQuantity] = useState(1);
  const [pinCode, setPinCode] = useState("");
  const [deliveryState, setDeliveryState] = useState<"idle" | "loading" | "available" | "unavailable" | "invalid">("idle");
  const [deliveryMessage, setDeliveryMessage] = useState("");
  const [isAddingToCart, setIsAddingToCart] = useState(false);

  // Personalization State
  const [personalisationData, setPersonalisationData] = useState<Record<string, string>>({});

  const toggleWishlist = () => {
    setIsWishlisted(!isWishlisted);
    toast(isWishlisted ? "Removed from wishlist" : "Added to wishlist", {
      position: "bottom-center"
    });
  };

  const handleQuantity = (type: "inc" | "dec") => {
    if (type === "inc" && quantity < (product.stock || 10)) {
      setQuantity(q => q + 1);
    } else if (type === "dec" && quantity > 1) {
      setQuantity(q => q - 1);
    }
  };

  const checkDelivery = (e: React.FormEvent) => {
    e.preventDefault();
    if (pinCode.length !== 6 || !/^\d+$/.test(pinCode)) {
      setDeliveryState("invalid");
      setDeliveryMessage("Please enter a valid 6-digit PIN code.");
      return;
    }

    setDeliveryState("loading");
    setDeliveryMessage("Checking availability...");

    // Mock API Call
    setTimeout(() => {
      if (pinCode.startsWith("4")) {
        setDeliveryState("unavailable");
        setDeliveryMessage("Delivery isn't currently available to this location.");
      } else {
        setDeliveryState("available");
        setDeliveryMessage(product.sameDayAvailable ? "Same-day delivery available to " + pinCode : "Delivery by tomorrow to " + pinCode);
      }
    }, 1000);
  };

  const handleAddToCart = () => {
    // Validate required personalization
    if (product.personalisationOptions) {
      const missing = product.personalisationOptions.find(opt => opt.required && !personalisationData[opt.label]);
      if (missing) {
        toast.error(`Please provide ${missing.label} for personalisation.`, { position: "top-center" });
        return;
      }
    }

    setIsAddingToCart(true);

    const selectedPers = [];
    if (product.personalisationOptions) {
      for (const opt of product.personalisationOptions) {
        if (personalisationData[opt.label]) {
          selectedPers.push({ label: opt.label, value: personalisationData[opt.label] });
        }
      }
    }

    const newItem = {
      id: `${product.id}-${Date.now()}`, // Temporary unique ID; exact duplicates merged by Context
      productId: product.id,
      product: product,
      quantity,
      personalisation: selectedPers.length > 0 ? selectedPers : undefined
    };

    setTimeout(() => {
      addItem(newItem);
      setIsAddingToCart(false);
      toast.success(`${quantity}x ${product.title} added to cart`, {
        position: "top-center",
        action: {
          label: "View Cart",
          onClick: () => console.log("Navigate to cart")
        }
      });
    }, 800);
  };

  return (
    <div className="flex flex-col w-full text-left">

      {/* Title & Metadata */}
      <div className="flex flex-col mb-6">
        <div className="flex items-start justify-between gap-4 mb-3">
          <h1 className="font-heading text-[28px] md:text-[34px] leading-[1.15] text-[#183330] font-medium">
            {product.title}
          </h1>
          <Button 
            variant="ghost" 
            size="icon" 
            onClick={toggleWishlist}
            className="shrink-0 w-11 h-11 rounded-full text-[#183330] hover:bg-[#F4F2EA]"
            aria-label={isWishlisted ? "Remove from wishlist" : "Add to wishlist"}
          >
            <Heart 
              className={cn("w-6 h-6 transition-colors", isWishlisted && "fill-[#D2A01F] text-[#D2A01F]")} 
              strokeWidth={isWishlisted ? 0 : 1.5}
            />
          </Button>
        </div>

        {/* Rating */}
        {product.rating && (
          <div className="flex items-center gap-1.5 text-[14px] text-[#5F706C] mb-4">
            <div className="flex items-center text-[#D2A01F]">
              <Star className="w-[16px] h-[16px] fill-current" />
            </div>
            <span className="font-medium text-[#183330]">{product.rating}</span>
            <span className="underline underline-offset-4 hover:text-[#183330] cursor-pointer">
              ({product.reviewCount} reviews)
            </span>
          </div>
        )}

        {/* Pricing */}
        <div className="flex items-baseline gap-3 mb-2">
          <span className="text-[24px] font-semibold text-[#183330]">
            {product.currency || "₹"}{product.price.toLocaleString("en-IN")}
          </span>
          {product.compareAtPrice && (
            <span className="text-[16px] text-[#5F706C] line-through">
              {product.currency || "₹"}{product.compareAtPrice.toLocaleString("en-IN")}
            </span>
          )}
          {product.discountPercentage && (
            <span className="text-[13px] font-semibold text-[#D2A01F] tracking-wide ml-1">
              {product.discountPercentage}% OFF
            </span>
          )}
        </div>
        <span className="text-[13px] text-[#5F706C]">Inclusive of all taxes</span>
      </div>

      <Separator className="bg-[#E4E7E2] mb-8" />

      {/* Description Preview */}
      {product.description && (
        <div className="mb-8">
          <p className="text-[15px] text-[#5F706C] leading-relaxed">
            {product.description}
          </p>
        </div>
      )}

      {/* Personalisation Form */}
      {product.isPersonalised && product.personalisationOptions && (
        <div className="mb-8 p-5 bg-[#F4F2EA] border border-[#E4E7E2] rounded-lg flex flex-col gap-5">
          <div className="flex items-center gap-2 mb-1">
            <h3 className="text-[13px] font-bold tracking-widest text-[#183330] uppercase">Make it personal</h3>
          </div>

          {product.personalisationOptions.map((opt, idx) => (
            <div key={idx} className="flex flex-col gap-2">
              <div className="flex justify-between items-end">
                <Label htmlFor={`pers-${idx}`} className="text-[14px] font-medium text-[#183330]">
                  {opt.label} {opt.required && <span className="text-[#D2A01F]">*</span>}
                </Label>
                {opt.maxLength && (
                  <span className="text-[12px] text-[#5F706C]">
                    {(personalisationData[opt.label] || "").length} / {opt.maxLength}
                  </span>
                )}
              </div>

              {opt.type === "text" && (
                <Input 
                  id={`pers-${idx}`}
                  maxLength={opt.maxLength}
                  placeholder={`Enter ${opt.label.toLowerCase()}`}
                  className="bg-white border-[#E4E7E2] focus-visible:ring-[#07514D] h-11"
                  value={personalisationData[opt.label] || ""}
                  onChange={(e) => setPersonalisationData({...personalisationData, [opt.label]: e.target.value})}
                />
              )}

              {opt.type === "photo" && (
                <div className="flex items-center justify-center w-full">
                  <label htmlFor={`pers-${idx}`} className="flex flex-col items-center justify-center w-full h-24 border-2 border-[#E4E7E2] border-dashed rounded-lg cursor-pointer bg-white hover:bg-[#FCFAF5] transition-colors">
                    <div className="flex flex-col items-center justify-center pt-5 pb-6">
                      <p className="text-[13px] font-medium text-[#07514D]">Click to upload photo</p>
                      <p className="text-[12px] text-[#5F706C] mt-1">SVG, PNG, JPG or GIF (MAX. 5MB)</p>
                    </div>
                    <input id={`pers-${idx}`} type="file" className="hidden" accept="image/*" />
                  </label>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Delivery Checker */}
      <div className="mb-8 flex flex-col gap-3">
        <h3 className="text-[14px] font-medium text-[#183330] flex items-center gap-2">
          <MapPin className="w-4 h-4 text-[#5F706C]" /> Check Delivery
        </h3>
        <form onSubmit={checkDelivery} className="flex gap-3">
          <Input 
            value={pinCode}
            onChange={(e) => setPinCode(e.target.value)}
            placeholder="Enter PIN code" 
            maxLength={6}
            className="h-12 bg-white border-[#E4E7E2] focus-visible:ring-[#07514D] max-w-[200px] text-[15px]"
          />
          <Button 
            type="submit" 
            variant="outline" 
            className="h-12 px-6 rounded-md border-[#E4E7E2] text-[#183330] hover:bg-[#F4F2EA] font-medium"
            disabled={deliveryState === "loading"}
          >
            Check
          </Button>
        </form>
        {deliveryMessage && (
          <p className={cn(
            "text-[13px] mt-1 font-medium flex items-start gap-1.5",
            deliveryState === "available" ? "text-[#07514D]" : 
            deliveryState === "invalid" || deliveryState === "unavailable" ? "text-red-700" : "text-[#5F706C]"
          )}>
            {deliveryState === "available" && <Check className="w-4 h-4 shrink-0 mt-0.5" />}
            {deliveryMessage}
          </p>
        )}
      </div>

      {/* Purchase Actions */}
      <div className="flex flex-col gap-4 mb-10">
        <div className="flex items-center gap-4">
          {/* Quantity */}
          <div className="flex items-center border border-[#E4E7E2] rounded-md h-12 w-[120px] bg-white shrink-0">
            <button 
              onClick={() => handleQuantity("dec")}
              className="w-10 h-full flex items-center justify-center text-[#183330] hover:bg-[#F4F2EA] disabled:opacity-50 transition-colors"
              disabled={quantity <= 1}
              aria-label="Decrease quantity"
            >
              <Minus className="w-4 h-4" />
            </button>
            <span className="flex-1 text-center text-[15px] font-medium text-[#183330]">{quantity}</span>
            <button 
              onClick={() => handleQuantity("inc")}
              className="w-10 h-full flex items-center justify-center text-[#183330] hover:bg-[#F4F2EA] disabled:opacity-50 transition-colors"
              disabled={quantity >= (product.stock || 10)}
              aria-label="Increase quantity"
            >
              <Plus className="w-4 h-4" />
            </button>
          </div>

          <Button 
            onClick={handleAddToCart}
            disabled={isAddingToCart}
            className="flex-1 h-12 bg-[#07514D] hover:bg-[#043F3C] text-[#FCFAF5] font-medium text-[15px] rounded-md transition-all disabled:opacity-80"
          >
            {isAddingToCart ? "Adding..." : "Add to Cart"}
          </Button>
        </div>

        <Button 
          variant="outline"
          className="w-full h-12 border-[#183330] text-[#183330] hover:bg-[#F4F2EA] font-medium text-[15px] rounded-md transition-colors"
        >
          Buy Now
        </Button>
      </div>

      {/* Trust Highlights */}
      <div className="grid grid-cols-3 gap-4 py-6 border-y border-[#E4E7E2] mb-10">
        <div className="flex flex-col items-center text-center gap-2">
          <ShieldCheck className="w-6 h-6 text-[#07514D]" strokeWidth={1.5} />
          <span className="text-[12px] font-medium text-[#183330]">Secure Payments</span>
        </div>
        <div className="flex flex-col items-center text-center gap-2 border-x border-[#E4E7E2]">
          <Truck className="w-6 h-6 text-[#07514D]" strokeWidth={1.5} />
          <span className="text-[12px] font-medium text-[#183330]">Pan-India Delivery</span>
        </div>
        <div className="flex flex-col items-center text-center gap-2">
          <Gift className="w-6 h-6 text-[#07514D]" strokeWidth={1.5} />
          <span className="text-[12px] font-medium text-[#183330]">Premium Packaging</span>
        </div>
      </div>

      {/* Accordions for Details */}
      <Accordion defaultValue={["details"]} className="w-full">
        <AccordionItem value="details" className="border-b border-[#E4E7E2] py-2">
          <AccordionTrigger className="text-[15px] font-medium text-[#183330] hover:no-underline hover:text-[#07514D] py-3">
            Product Details
          </AccordionTrigger>
          <AccordionContent className="pt-1 pb-4 text-[14px] text-[#5F706C] leading-relaxed">
            {product.description || "Thoughtfully designed to create a lasting impression. This premium gift is meticulously crafted using high-quality materials to ensure it stands the test of time."}

            {product.specifications && (
              <div className="mt-6">
                <ul className="flex flex-col gap-3">
                  {Object.entries(product.specifications).map(([key, value]) => (
                    <li key={key} className="flex flex-col sm:flex-row sm:gap-4 border-b border-[#E4E7E2]/50 pb-2 last:border-0 last:pb-0">
                      <span className="text-[13px] font-medium text-[#183330] sm:w-[120px] shrink-0">{key}</span>
                      <span className="text-[14px] text-[#5F706C]">{value}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </AccordionContent>
        </AccordionItem>

        <AccordionItem value="delivery" className="border-b border-[#E4E7E2] py-2">
          <AccordionTrigger className="text-[15px] font-medium text-[#183330] hover:no-underline hover:text-[#07514D] py-3">
            Delivery & Returns
          </AccordionTrigger>
          <AccordionContent className="pt-1 pb-4 text-[14px] text-[#5F706C] leading-relaxed">
            <p className="mb-3">Standard delivery takes 3-5 business days. Same-day delivery is available in select cities for orders placed before 2 PM.</p>
            <p>Personalised items cannot be returned or exchanged unless there is a manufacturing defect or transit damage. Please record an unboxing video to claim transit damage.</p>
          </AccordionContent>
        </AccordionItem>
      </Accordion>

    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { useRouter, useSearchParams, usePathname } from "next/navigation";
import { SlidersHorizontal, ChevronDown, X } from "lucide-react";

import { Product } from "@/data/products";
import { ProductCard } from "./ProductCard";
import { ProductSkeleton } from "./ProductSkeleton";

import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetHeader, SheetTitle, SheetTrigger } from "@/components/ui/sheet";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "@/components/ui/accordion";
import { Checkbox } from "@/components/ui/checkbox";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";

// --- Types ---
interface ProductListingProps {
  initialProducts: Product[];
  totalCount: number;
  searchQuery?: string;
}

const SORT_OPTIONS = [
  { value: "recommended", label: "Recommended" },
  { value: "newest", label: "Newest" },
  { value: "price-low", label: "Price: Low to High" },
  { value: "price-high", label: "Price: High to Low" },
  { value: "rating", label: "Customer Rating" },
  { value: "bestselling", label: "Bestselling" },
];

const PRICE_RANGES = [
  { id: "under-499", label: "Under ₹499" },
  { id: "500-999", label: "₹500 – ₹999" },
  { id: "1000-2499", label: "₹1,000 – ₹2,499" },
  { id: "2500-plus", label: "₹2,500+" },
];

const RECIPIENTS = [
  { id: "her", label: "For Her" },
  { id: "him", label: "For Him" },
  { id: "mom", label: "For Mom" },
  { id: "dad", label: "For Dad" },
  { id: "wife", label: "For Wife" },
  { id: "husband", label: "For Husband" },
  { id: "friends", label: "For Friends" },
  { id: "kids", label: "For Kids" },
];

const DELIVERY = [
  { id: "same-day", label: "Same Day" },
  { id: "next-day", label: "Next Day" },
  { id: "scheduled", label: "Scheduled" },
];

// --- Product Listing Component ---
export function ProductListing({ initialProducts, totalCount, searchQuery }: ProductListingProps) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  // URL state
  const [isPending, setIsPending] = useState(false);

  // Create a new URLSearchParams object when updating
  const createQueryString = useCallback(
    (name: string, value: string) => {
      const params = new URLSearchParams(searchParams.toString());
      if (value) {
        params.set(name, value);
      } else {
        params.delete(name);
      }
      return params.toString();
    },
    [searchParams]
  );

  const toggleQueryArray = useCallback(
    (name: string, value: string) => {
      const params = new URLSearchParams(searchParams.toString());
      const currentValues = params.get(name)?.split(",") || [];

      let newValues;
      if (currentValues.includes(value)) {
        newValues = currentValues.filter((v) => v !== value);
      } else {
        newValues = [...currentValues, value];
      }

      if (newValues.length > 0) {
        params.set(name, newValues.join(","));
      } else {
        params.delete(name);
      }

      return params.toString();
    },
    [searchParams]
  );

  const handleSortChange = (value: string) => {
    setIsPending(true);
    router.push(`${pathname}?${createQueryString("sort", value)}`, { scroll: false });
  };

  const handleFilterToggle = (category: string, value: string) => {
    setIsPending(true);
    router.push(`${pathname}?${toggleQueryArray(category, value)}`, { scroll: false });
  };

  const handleRadioFilter = (category: string, value: string) => {
    setIsPending(true);
    router.push(`${pathname}?${createQueryString(category, value)}`, { scroll: false });
  };

  const clearFilters = () => {
    setIsPending(true);
    const params = new URLSearchParams(searchParams.toString());
    params.delete("price");
    params.delete("recipient");
    params.delete("personalised");
    params.delete("delivery");
    params.delete("rating");
    router.push(`${pathname}?${params.toString()}`, { scroll: false });
  };

  // Mock loading effect when params change
  useEffect(() => {
    const timer = setTimeout(() => setIsPending(false), 400);
    return () => clearTimeout(timer);
  }, [searchParams]);

  // Derived state from URL
  const currentSort = searchParams.get("sort") || "recommended";
  const selectedPrices = searchParams.get("price")?.split(",") || [];
  const selectedRecipients = searchParams.get("recipient")?.split(",") || [];
  const selectedDelivery = searchParams.get("delivery")?.split(",") || [];
  const selectedPersonalised = searchParams.get("personalised") || "all";

  // Check if any filters are active
  const hasActiveFilters = selectedPrices.length > 0 || selectedRecipients.length > 0 || selectedDelivery.length > 0 || selectedPersonalised !== "all";

  const FilterContent = () => (
    <div className="flex flex-col gap-6 w-full">
      {hasActiveFilters && (
        <div className="flex items-center justify-between pb-2 border-b border-[#E4E7E2]">
          <span className="text-[14px] font-medium text-[#183330]">Filters Applied</span>
          <button 
            onClick={clearFilters}
            className="text-[12px] font-medium text-[#5F706C] hover:text-[#07514D] underline underline-offset-2 transition-colors"
          >
            Clear all
          </button>
        </div>
      )}

      <Accordion defaultValue={["price", "recipient", "personalised", "delivery"]} className="w-full">

        {/* Price Filter */}
        <AccordionItem value="price" className="border-b border-[#E4E7E2] py-2">
          <AccordionTrigger className="text-[15px] font-medium text-[#183330] hover:no-underline hover:text-[#07514D] py-3">
            Price
          </AccordionTrigger>
          <AccordionContent className="pt-1 pb-4">
            <div className="flex flex-col gap-3.5">
              {PRICE_RANGES.map((range) => (
                <div key={range.id} className="flex items-center space-x-3">
                  <Checkbox 
                    id={`price-${range.id}`} 
                    checked={selectedPrices.includes(range.id)}
                    onCheckedChange={() => handleFilterToggle("price", range.id)}
                    className="border-[#5F706C] data-[state=checked]:bg-[#07514D] data-[state=checked]:border-[#07514D] rounded-[4px]"
                  />
                  <Label htmlFor={`price-${range.id}`} className="text-[14px] font-normal text-[#183330] cursor-pointer">
                    {range.label}
                  </Label>
                </div>
              ))}
            </div>
          </AccordionContent>
        </AccordionItem>

        {/* Recipient Filter */}
        <AccordionItem value="recipient" className="border-b border-[#E4E7E2] py-2">
          <AccordionTrigger className="text-[15px] font-medium text-[#183330] hover:no-underline hover:text-[#07514D] py-3">
            Recipient
          </AccordionTrigger>
          <AccordionContent className="pt-1 pb-4">
            <div className="flex flex-col gap-3.5">
              {RECIPIENTS.map((rec) => (
                <div key={rec.id} className="flex items-center space-x-3">
                  <Checkbox 
                    id={`rec-${rec.id}`} 
                    checked={selectedRecipients.includes(rec.id)}
                    onCheckedChange={() => handleFilterToggle("recipient", rec.id)}
                    className="border-[#5F706C] data-[state=checked]:bg-[#07514D] data-[state=checked]:border-[#07514D] rounded-[4px]"
                  />
                  <Label htmlFor={`rec-${rec.id}`} className="text-[14px] font-normal text-[#183330] cursor-pointer">
                    {rec.label}
                  </Label>
                </div>
              ))}
            </div>
          </AccordionContent>
        </AccordionItem>

        {/* Personalisation Filter (Radio) */}
        <AccordionItem value="personalised" className="border-b border-[#E4E7E2] py-2">
          <AccordionTrigger className="text-[15px] font-medium text-[#183330] hover:no-underline hover:text-[#07514D] py-3">
            Personalisation
          </AccordionTrigger>
          <AccordionContent className="pt-1 pb-4">
            <RadioGroup 
              value={selectedPersonalised} 
              onValueChange={(val) => handleRadioFilter("personalised", val)}
              className="flex flex-col gap-3.5"
            >
              <div className="flex items-center space-x-3">
                <RadioGroupItem value="all" id="pers-all" className="border-[#5F706C] text-[#07514D]" />
                <Label htmlFor="pers-all" className="text-[14px] font-normal text-[#183330] cursor-pointer">All Gifts</Label>
              </div>
              <div className="flex items-center space-x-3">
                <RadioGroupItem value="true" id="pers-true" className="border-[#5F706C] text-[#07514D]" />
                <Label htmlFor="pers-true" className="text-[14px] font-normal text-[#183330] cursor-pointer">Personalised Only</Label>
              </div>
              <div className="flex items-center space-x-3">
                <RadioGroupItem value="false" id="pers-false" className="border-[#5F706C] text-[#07514D]" />
                <Label htmlFor="pers-false" className="text-[14px] font-normal text-[#183330] cursor-pointer">Non-Personalised</Label>
              </div>
            </RadioGroup>
          </AccordionContent>
        </AccordionItem>

        {/* Delivery Filter */}
        <AccordionItem value="delivery" className="border-b-0 py-2">
          <AccordionTrigger className="text-[15px] font-medium text-[#183330] hover:no-underline hover:text-[#07514D] py-3">
            Delivery
          </AccordionTrigger>
          <AccordionContent className="pt-1 pb-4">
            <div className="flex flex-col gap-3.5">
              {DELIVERY.map((del) => (
                <div key={del.id} className="flex items-center space-x-3">
                  <Checkbox 
                    id={`del-${del.id}`} 
                    checked={selectedDelivery.includes(del.id)}
                    onCheckedChange={() => handleFilterToggle("delivery", del.id)}
                    className="border-[#5F706C] data-[state=checked]:bg-[#07514D] data-[state=checked]:border-[#07514D] rounded-[4px]"
                  />
                  <Label htmlFor={`del-${del.id}`} className="text-[14px] font-normal text-[#183330] cursor-pointer">
                    {del.label}
                  </Label>
                </div>
              ))}
            </div>
          </AccordionContent>
        </AccordionItem>
      </Accordion>
    </div>
  );

  return (
    <div className="w-full flex flex-col">

      {/* Product Toolbar */}
      <div className="flex items-center justify-between py-4 border-y border-[#E4E7E2] mb-8 lg:mb-10 bg-[#FCFAF5] sticky top-0 z-30 lg:relative lg:top-auto lg:z-auto">

        {/* Mobile Filter Trigger */}
        <div className="lg:hidden">
          <Sheet>
            <SheetTrigger render={
              <Button variant="outline" size="sm" className="h-10 px-4 rounded-md border-[#E4E7E2] text-[#183330] font-medium flex items-center gap-2" />
            }>
                <SlidersHorizontal className="w-4 h-4" />
                Filters
                {hasActiveFilters && (
                  <span className="w-2 h-2 rounded-full bg-[#D2A01F]" />
                )}
            </SheetTrigger>
            <SheetContent side="left" className="w-[85vw] sm:w-[380px] bg-[#FCFAF5] p-0 border-r-[#E4E7E2] flex flex-col">
              <SheetHeader className="p-5 border-b border-[#E4E7E2] text-left">
                <SheetTitle className="font-heading text-[22px] font-medium text-[#183330]">Filter Products</SheetTitle>
              </SheetHeader>
              <div className="flex-1 overflow-y-auto p-5">
                <FilterContent />
              </div>
              <div className="p-5 border-t border-[#E4E7E2] mt-auto bg-[#F4F2EA]">
                <Button className="w-full bg-[#07514D] hover:bg-[#043F3C] text-[#FCFAF5] rounded-md h-12 text-[15px] font-medium">
                  Show {totalCount} Results
                </Button>
              </div>
            </SheetContent>
          </Sheet>
        </div>

        {/* Desktop Filter Label */}
        <div className="hidden lg:flex items-center gap-2 w-[240px] xl:w-[280px] shrink-0">
          <SlidersHorizontal className="w-[18px] h-[18px] text-[#183330]" />
          <span className="text-[15px] font-medium text-[#183330]">Filters</span>
        </div>

        {/* Center Item Count */}
        <div className="text-[14px] lg:text-[15px] font-medium text-[#5F706C] flex-1 text-center lg:text-left">
          {totalCount} gifts
        </div>

        {/* Sort Dropdown */}
        <div className="flex items-center gap-3">
          <span className="hidden md:inline-block text-[14px] text-[#5F706C] font-medium">Sort by:</span>
          <Select value={currentSort} onValueChange={(val) => val && handleSortChange(val)}>
            <SelectTrigger className="w-[140px] md:w-[180px] h-10 border-none bg-transparent shadow-none focus:ring-0 p-0 justify-end gap-1.5 text-[14px] md:text-[15px] font-medium text-[#183330]">
              <SelectValue placeholder="Sort" />
            </SelectTrigger>
            <SelectContent align="end" className="bg-[#FCFAF5] border-[#E4E7E2] rounded-md shadow-lg min-w-[200px]">
              {SORT_OPTIONS.map((opt) => (
                <SelectItem 
                  key={opt.value} 
                  value={opt.value}
                  className="text-[14px] py-2.5 cursor-pointer focus:bg-[#F4F2EA] focus:text-[#07514D]"
                >
                  {opt.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Main Layout Grid */}
      <div className="flex flex-col lg:flex-row gap-8 xl:gap-12 w-full items-start">

        {/* Desktop Sidebar */}
        <aside className="hidden lg:block w-[240px] xl:w-[280px] shrink-0 sticky top-12">
          <FilterContent />
        </aside>

        {/* Product Grid Area */}
        <div className="flex-1 w-full">
          {/* Active Filters Display */}
          {hasActiveFilters && (
            <div className="hidden lg:flex flex-wrap items-center gap-2 mb-6">
              {[...selectedPrices, ...selectedRecipients, ...selectedDelivery].map(filter => (
                <div key={filter} className="flex items-center gap-1.5 px-3 py-1.5 bg-[#F4F2EA] border border-[#E4E7E2] rounded-full text-[13px] font-medium text-[#183330]">
                  {filter}
                  <button 
                    onClick={() => {
                      if (PRICE_RANGES.find(p => p.id === filter)) handleFilterToggle("price", filter);
                      else if (RECIPIENTS.find(r => r.id === filter)) handleFilterToggle("recipient", filter);
                      else handleFilterToggle("delivery", filter);
                    }}
                    className="text-[#5F706C] hover:text-[#183330] transition-colors"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              ))}
              {selectedPersonalised !== "all" && (
                <div className="flex items-center gap-1.5 px-3 py-1.5 bg-[#F4F2EA] border border-[#E4E7E2] rounded-full text-[13px] font-medium text-[#183330]">
                  {selectedPersonalised === "true" ? "Personalised" : "Non-Personalised"}
                  <button 
                    onClick={() => handleRadioFilter("personalised", "all")}
                    className="text-[#5F706C] hover:text-[#183330] transition-colors"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                </div>
              )}
              <button 
                onClick={clearFilters}
                className="text-[13px] font-medium text-[#5F706C] hover:text-[#07514D] underline underline-offset-2 ml-2 transition-colors"
              >
                Clear all
              </button>
            </div>
          )}

          {/* Grid Container */}
          <div className="grid grid-cols-2 md:grid-cols-3 xl:grid-cols-4 gap-x-4 gap-y-10 md:gap-x-6 md:gap-y-12 w-full">
            {isPending ? (
              // Loading State Skeletons
              Array.from({ length: 8 }).map((_, i) => (
                <ProductSkeleton key={`skeleton-${i}`} />
              ))
            ) : initialProducts.length > 0 ? (
              initialProducts.map((product) => (
                <ProductCard key={product.id} product={product} />
              ))
            ) : (
              <div className="col-span-2 md:col-span-3 xl:col-span-4 flex flex-col items-center justify-center py-16 lg:py-24 text-center">
                <div className="w-16 h-16 rounded-full bg-[#F4F2EA] flex items-center justify-center mb-6">
                  <SlidersHorizontal className="w-8 h-8 text-[#5F706C]" />
                </div>
                <h3 className="font-heading text-[24px] lg:text-[28px] text-[#183330] font-medium mb-3">
                  {searchQuery ? `No gifts found for "${searchQuery}"` : "No gifts found"}
                </h3>
                <p className="text-[15px] text-[#5F706C] max-w-md mb-8">
                  {searchQuery 
                    ? "Try checking your spelling, use more general terms, or explore some of our popular gifting categories."
                    : "Try adjusting your filters or explore more gifting options to find the perfect present."}
                </p>
                <div className="flex flex-col sm:flex-row items-center gap-4 mb-12">
                  <Button 
                    variant="outline" 
                    onClick={clearFilters}
                    className="h-12 px-6 rounded-md border-[#183330] text-[#183330] hover:bg-[#F4F2EA] font-medium"
                  >
                    Clear Filters
                  </Button>
                  <a 
                    href="/category/all"
                    className="inline-flex items-center justify-center h-12 px-6 rounded-md bg-[#07514D] hover:bg-[#043F3C] text-[#FCFAF5] font-medium transition-colors"
                  >
                    Browse All Gifts
                  </a>
                </div>

                {searchQuery && (
                  <div className="flex flex-col items-center border-t border-[#E4E7E2] pt-10 w-full max-w-xl">
                    <h4 className="text-[14px] font-semibold text-[#183330] uppercase tracking-wider mb-6">Popular Searches</h4>
                    <div className="flex flex-wrap justify-center gap-3">
                      {["Birthday Gifts", "Personalised Gifts", "Gift Hampers", "Flowers", "Gifts for Her", "Same-Day Gifts"].map((term) => (
                        <a 
                          key={term}
                          href={`/search?q=${encodeURIComponent(term)}`}
                          className="px-4 py-2 bg-white border border-[#E4E7E2] rounded-full text-[13px] font-medium text-[#183330] hover:border-[#183330] transition-colors"
                        >
                          {term}
                        </a>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Load More Pagination */}
          {initialProducts.length > 0 && initialProducts.length < totalCount && (
            <div className="w-full flex justify-center mt-16 lg:mt-24 border-t border-[#E4E7E2] pt-12">
              <div className="flex flex-col items-center">
                <span className="text-[14px] text-[#5F706C] font-medium mb-4">
                  Showing {initialProducts.length} of {totalCount} gifts
                </span>
                <Button 
                  variant="outline" 
                  className="h-12 px-8 rounded-md border-[#E4E7E2] bg-white text-[#183330] hover:border-[#183330] hover:bg-white font-medium text-[15px] transition-all min-w-[200px]"
                >
                  Load More
                </Button>
              </div>
            </div>
          )}

        </div>

      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { campaigns, Campaign } from "@/data/campaigns";
