  if (!timeline || timeline.length === 0) {
    return (
      <div className="text-[14px] text-[#5F706C] p-4 bg-[#FCFAF5] rounded-md border border-[#E4E7E2]">
        Timeline details are currently unavailable. Current status: <span className="font-medium text-[#183330] capitalize">{currentStatus.replace("_", " ")}</span>
      </div>
    );
  }

  return (
    <div className="relative pl-3 md:pl-0">
      {/* Vertical line connecting nodes */}
      <div className="absolute left-[27px] top-[24px] bottom-[24px] w-[2px] bg-[#E4E7E2] z-0 md:left-[35px]" />

      <div className="flex flex-col gap-8 relative z-10">
        {timeline.map((event, index) => {
          const isCurrent = event.status === currentStatus;
          const isCompleted = event.completed;
          const isFuture = !isCompleted && !isCurrent;

          return (
            <div key={index} className={cn("flex gap-4 md:gap-6", isFuture ? "opacity-50" : "opacity-100")}>

              {/* Status Indicator */}
              <div className="relative flex flex-col items-center mt-1">
                <div 
                  className={cn(
                    "w-8 h-8 rounded-full flex items-center justify-center border-2 transition-colors z-10 shrink-0",
                    isCompleted ? "bg-[#07514D] border-[#07514D] text-white" : 
                    isCurrent ? "bg-white border-[#07514D] text-[#07514D]" : 
                    "bg-white border-[#E4E7E2] text-[#E4E7E2]"
                  )}
                >
                  {isCompleted ? (
                    <Check className="w-4 h-4" strokeWidth={3} />
                  ) : isCurrent ? (
                    <div className="w-2.5 h-2.5 bg-[#07514D] rounded-full" />
                  ) : (
                    <div className="w-2 h-2 bg-[#E4E7E2] rounded-full" />
                  )}
                </div>
              </div>

              {/* Content */}
              <div className="flex flex-col flex-1 pb-1">
                <div className="flex flex-col md:flex-row md:justify-between md:items-baseline gap-1 md:gap-4 mb-1">
                  <h3 className={cn(
                    "text-[16px] font-medium",
                    isCurrent ? "text-[#183330]" : 
                    isCompleted ? "text-[#183330]" : 
                    "text-[#5F706C]"
                  )}>
                    {event.label}
                  </h3>
                  {event.timestamp && (
                    <span className={cn(
                      "text-[13px] md:text-right shrink-0",
                      isCurrent ? "text-[#07514D] font-medium" : "text-[#5F706C]"
                    )}>
                      {event.timestamp}
                    </span>
                  )}
                </div>

                {event.description && (
                  <p className="text-[14px] text-[#5F706C] mt-1 leading-relaxed">
                    {event.description}
                  </p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client"

import * as React from "react"
import { cn } from "cn"
import useEmblaCarousel, {
  type UseEmblaCarouselType,
} from "embla-carousel-react"

import { Button } from "@/components/ui/button"
import { ChevronLeftIcon, ChevronRightIcon } from "lucide-react"

type CarouselApi = UseEmblaCarouselType[1]
type UseCarouselParameters = Parameters<typeof useEmblaCarousel>
type CarouselOptions = UseCarouselParameters[0]
type CarouselPlugin = UseCarouselParameters[1]

type CarouselProps = {
  opts?: CarouselOptions
  plugins?: CarouselPlugin
  orientation?: "horizontal" | "vertical"
  setApi?: (api: CarouselApi) => void
}

type CarouselContextProps = {
  carouselRef: ReturnType<typeof useEmblaCarousel>[0]
  api: ReturnType<typeof useEmblaCarousel>[1]
  scrollPrev: () => void
  scrollNext: () => void
  canScrollPrev: boolean
  canScrollNext: boolean
} & CarouselProps

const CarouselContext = React.createContext<CarouselContextProps | null>(null)

function useCarousel() {
  const context = React.useContext(CarouselContext)

  if (!context) {
    throw new Error("useCarousel must be used within a <Carousel />")
  }

  return context
}

function Carousel({
  orientation = "horizontal",
  opts,
  setApi,
  plugins,
  className,
  children,
  ...props
}: React.ComponentProps<"div"> & CarouselProps) {
  const [carouselRef, api] = useEmblaCarousel(
    {
      ...opts,
      axis: orientation === "horizontal" ? "x" : "y",
    },
    plugins
  )
  const [canScrollPrev, setCanScrollPrev] = React.useState(false)
  const [canScrollNext, setCanScrollNext] = React.useState(false)

  const onSelect = React.useCallback((api: CarouselApi) => {
    if (!api) return
    setCanScrollPrev(api.canScrollPrev())
    setCanScrollNext(api.canScrollNext())
  }, [])

  const scrollPrev = React.useCallback(() => {
    api?.scrollPrev()
  }, [api])

  const scrollNext = React.useCallback(() => {
    api?.scrollNext()
  }, [api])

  const handleKeyDown = React.useCallback(
    (event: React.KeyboardEvent<HTMLDivElement>) => {
      if (event.key === "ArrowLeft") {
        event.preventDefault()
        scrollPrev()
      } else if (event.key === "ArrowRight") {
        event.preventDefault()
        scrollNext()
      }
    },
    [scrollPrev, scrollNext]
  )

  React.useEffect(() => {
    if (!api || !setApi) return
    setApi(api)
  }, [api, setApi])

  React.useEffect(() => {
    if (!api) return
    onSelect(api)
    api.on("reInit", onSelect)
    api.on("select", onSelect)

    return () => {
      api?.off("select", onSelect)
    }
  }, [api, onSelect])

  return (
    <CarouselContext.Provider
      value={{
        carouselRef,
        api: api,
        opts,
        orientation:
          orientation || (opts?.axis === "y" ? "vertical" : "horizontal"),
        scrollPrev,
        scrollNext,
        canScrollPrev,
        canScrollNext,
      }}
    >
      <div
        onKeyDownCapture={handleKeyDown}
        className={cn("relative", className)}
        role="region"
        aria-roledescription="carousel"
        data-slot="carousel"
        {...props}
      >
        {children}
      </div>
    </CarouselContext.Provider>
  )
}

function CarouselContent({ className, ...props }: React.ComponentProps<"div">) {
  const { carouselRef, orientation } = useCarousel()

  return (
    <div
      ref={carouselRef}
      className="overflow-hidden"
      data-slot="carousel-content"
    >
      <div
        className={cn(
          "flex",
          orientation === "horizontal" ? "-ml-4" : "-mt-4 flex-col",
          className
        )}
        {...props}
      />
    </div>
  )
}

function CarouselItem({ className, ...props }: React.ComponentProps<"div">) {
  const { orientation } = useCarousel()

  return (
    <div
      role="group"
      aria-roledescription="slide"
      data-slot="carousel-item"
      className={cn(
        "min-w-0 shrink-0 grow-0 basis-full",
        orientation === "horizontal" ? "pl-4" : "pt-4",
        className
      )}
      {...props}
    />
  )
}

function CarouselPrevious({
  className,
  variant = "outline",
  size = "icon-sm",
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollPrev, canScrollPrev } = useCarousel()

  return (
    <Button
      data-slot="carousel-previous"
      variant={variant}
      size={size}
      className={cn(
        "absolute touch-manipulation rounded-full",
        orientation === "horizontal"
          ? "inset-y-0 -left-12 my-auto"
          : "-top-12 left-1/2 -translate-x-1/2 rotate-90",
        className
      )}
      disabled={!canScrollPrev}
      onClick={scrollPrev}
      {...props}
    >
      <ChevronLeftIcon />
      <span className="sr-only">Previous slide</span>
    </Button>
  )
}

function CarouselNext({
  className,
  variant = "outline",
  size = "icon-sm",
  ...props
}: React.ComponentProps<typeof Button>) {
  const { orientation, scrollNext, canScrollNext } = useCarousel()

  return (
    <Button
      data-slot="carousel-next"
      variant={variant}
      size={size}
      className={cn(
        "absolute touch-manipulation rounded-full",
        orientation === "horizontal"
          ? "inset-y-0 -right-12 my-auto"
          : "-bottom-12 left-1/2 -translate-x-1/2 rotate-90",
        className
      )}
      disabled={!canScrollNext}
      onClick={scrollNext}
      {...props}
    >
      <ChevronRightIcon />
      <span className="sr-only">Next slide</span>
    </Button>
  )
}

export {
  type CarouselApi,
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselPrevious,
  CarouselNext,
  useCarousel,
}

export interface User {
  id: string;
  name: string;
  email?: string;
  phone: string;
  createdAt: string;
}

// Mock Database
const MOCK_USERS: Record<string, User> = {
  "9876543210": {
    id: "USR-001",
    name: "Ananya Sharma",
    email: "ananya.sharma@example.com",
    phone: "9876543210",
    createdAt: "2024-01-15T08:00:00Z",
  },
};

const MOCK_OTP = "123456";

export async function sendOtp(phoneOrEmail: string): Promise<{ success: boolean; isNewUser: boolean; message: string }> {
  return new Promise((resolve) => {
    setTimeout(() => {
      const isPhone = /^[0-9]{10}$/.test(phoneOrEmail.replace(/\D/g, ''));
      const normalizedPhone = phoneOrEmail.replace(/\D/g, '').slice(-10);

      const userExists = !!MOCK_USERS[normalizedPhone] || Object.values(MOCK_USERS).some(u => u.email === phoneOrEmail);

      resolve({
        success: true,
        isNewUser: !userExists,
        message: `OTP sent to ${phoneOrEmail}`,
      });
    }, 800);
  });
}

export async function verifyOtp(phoneOrEmail: string, otp: string, nameForSignup?: string): Promise<{ success: boolean; user?: User; error?: string }> {
  return new Promise((resolve) => {
    setTimeout(() => {
      if (otp !== MOCK_OTP) {
        resolve({ success: false, error: "Incorrect OTP. Please try again." });
        return;
      }

      const normalizedPhone = phoneOrEmail.replace(/\D/g, '').slice(-10) || "9999999999";

      let user = MOCK_USERS[normalizedPhone] || Object.values(MOCK_USERS).find(u => u.email === phoneOrEmail);

      if (!user) {
        // Create new user
        user = {
          id: `USR-${Math.random().toString(36).substring(2, 8)}`,
          name: nameForSignup || "Guest Customer",
          phone: normalizedPhone,
          email: phoneOrEmail.includes("@") ? phoneOrEmail : undefined,
          createdAt: new Date().toISOString(),
        };
        MOCK_USERS[normalizedPhone] = user;
      }

      resolve({ success: true, user });
    }, 1200);
  });
}
